import{_ as t,o as d,c as s,ag as a}from"./chunks/framework.BZohXCq9.js";const p=JSON.parse('{"title":"Teacher Dashboard -> My Students (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/teacher-dashboard/my-students.md","filePath":"modules/teacher-dashboard/my-students.md"}'),r={name:"modules/teacher-dashboard/my-students.md"};function o(l,e,n,i,c,u){return d(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="teacher-dashboard-my-students-deep" tabindex="-1">Teacher Dashboard -&gt; My Students (deep) <a class="header-anchor" href="#teacher-dashboard-my-students-deep" aria-label="Permalink to &quot;Teacher Dashboard -&gt; My Students (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>teacher-dashboard</code><br><strong>Feature:</strong> <code>my-students</code><br><strong>Routes:</strong> <code>/teacher-dashboard/my-students</code>, <code>/teacher-dashboard/studentProgress/:studentId</code></p><p>This module lets instructors browse their students and drill into each student’s lesson/progress dashboard.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Show students linked to the instructor.</li><li>Filter/sort student list using backend-driven filters.</li><li>Open a student progress detail page.</li><li>Reuse student dashboard-style summary data for instructor visibility.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/teacher-dashboard/MyStudentsTrack.tsx</code></td><td>Students list page</td><td>Calls <code>GET_ALL_STUDENTS</code> with filter input; renders student cards and filter controls.</td></tr><tr><td><code>Frontend/src/pages/private/teacher-dashboard/StudentProgress.tsx</code></td><td>Student detail page</td><td>Uses <code>useStudentDashboard</code> to load the student progress/dashboard payload.</td></tr><tr><td><code>Frontend/src/hooks/UseStudentDashboard.ts</code></td><td>Student detail hook</td><td>Wraps the student dashboard query.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/StudentsTracking/FiltersComponent.tsx</code></td><td>Filter UI</td><td>Collects backend filter parameters.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/StudentsTracking/StudentCard.tsx</code></td><td>Student summary card</td><td>Links to student progress page.</td></tr><tr><td><code>Frontend/src/graphql/Queries/StudentQueries.ts</code></td><td>Student GraphQL</td><td>Defines <code>GET_ALL_STUDENTS</code> and <code>GET_STUDENT_DASHBOARD</code>.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="students-list" tabindex="-1">Students list <a class="header-anchor" href="#students-list" aria-label="Permalink to &quot;Students list&quot;">​</a></h3><ul><li><code>GET_ALL_STUDENTS</code><ul><li>Query field: <code>getAllStudents(filter: StudentFilter)</code></li><li>Used by <code>MyStudentsTrack.tsx</code></li><li>Backend filtering/sorting is applied server-side</li></ul></li></ul><h3 id="student-detail" tabindex="-1">Student detail <a class="header-anchor" href="#student-detail" aria-label="Permalink to &quot;Student detail&quot;">​</a></h3><ul><li><code>GET_STUDENT_DASHBOARD</code><ul><li>Query field: <code>getStudentDashboardDetails(studentId: ID!)</code></li><li>Used through <code>useStudentDashboard</code></li><li>Provides student info, lesson stats, graph stats, completed bookings, and uncompleted bookings</li></ul></li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>Files: <ul><li><code>server/src/graphql/typeDefs/student.typeDefs.js</code></li><li><code>server/src/graphql/typeDefs/studentBooking.typeDefs.js</code></li></ul></li><li>Relevant query fields: <ul><li><code>getAllStudents(filter: StudentFilter): [Student!]!</code></li><li><code>getStudentDashboardDetails(studentId: ID!): StudentDashboardDetails</code></li><li>related supporting fields: <code>getStudentLessonHours</code>, <code>getStudentProgress</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>Files: <ul><li><code>server/src/graphql/resolvers/student.resolver.js</code></li><li><code>server/src/graphql/resolvers/studentBooking.resolver.js</code></li></ul></li><li>Relevant resolvers: <ul><li><code>Query.getAllStudents</code></li><li><code>Query.getStudentDashboardDetails</code></li><li>related support: <code>getStudentLessonHours</code>, <code>getStudentProgress</code></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/User.js</code></td><td>Student profile data</td></tr><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Booking/lesson progress data</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Instructor opens <code>/teacher-dashboard/my-students</code>.</li><li><code>MyStudentsTrack.tsx</code> sends <code>GET_ALL_STUDENTS(filter)</code>.</li><li>Backend returns students filtered/sorted according to the supplied filter.</li><li>Clicking a student opens <code>/teacher-dashboard/studentProgress/:studentId</code>.</li><li><code>StudentProgress.tsx</code> uses <code>useStudentDashboard</code>, which calls <code>getStudentDashboardDetails(studentId)</code>.</li><li>Backend returns a dashboard-style payload that the teacher detail page renders as progress charts/tables/cards.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>The list page treats filtering as backend-driven and does not re-filter the dataset in the client beyond simple memo passthrough.</li><li><code>TeacherLayout.tsx</code> also uses <code>GET_ALL_STUDENTS</code> separately to seed chat conversations for students with lesson history.</li></ul>',23)])])}const b=t(r,[["render",o]]);export{p as __pageData,b as default};
